function fillSudoku(grid, numUndefined) {
  // Shuffle an array of numbers from 1 to 9
  const nums = Array.from({length: 9}, (_, i) => i + 1);
  for (let i = 8; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [nums[i], nums[j]] = [nums[j], nums[i]];
  }

  // Define a recursive helper function to fill the grid
  function fillCell(row, col) {
    // If we've filled all the cells, we're done
    if (row === 9) {
      return true;
    }

    const nextRow = col === 8 ? row + 1 : row;
    const nextCol = col === 8 ? 0 : col + 1;

    // If the cell is already defined, move to the next cell
    if (grid[row][col] !== undefined) {
      return fillCell(nextRow, nextCol);
    }

    // Try each of the shuffled numbers in this cell
    for (let num of nums) {
      if (isValid(grid, row, col, num)) {
        grid[row][col] = num;
        if (fillCell(nextRow, nextCol)) {
          return true;
        }
      }
    }

    // If we've tried all the numbers and none work, reset the cell and backtrack
    grid[row][col] = undefined;
    return false;
  }

  // Define a helper function to check if a number is valid in a given cell
  function isValid(grid, row, col, num) {
    // Check row and column
    for (let i = 0; i < 9; i++) {
      if (grid[row][i] === num || grid[i][col] === num) {
        return false;
      }
    }

    // Check 3x3 box
    const boxRow = Math.floor(row / 3) * 3;
    const boxCol = Math.floor(col / 3) * 3;
    for (let i = boxRow; i < boxRow + 3; i++) {
      for (let j = boxCol; j < boxCol + 3; j++) {
        if (grid[i][j] === num) {
          return false;
        }
      }
    }

    // If all checks pass, the number is valid
    return true;
  }

  // Call the recursive helper function to fill the grid
  fillCell(0, 0);

  // Randomly remove some cells
  const indices = Array.from({length: 81}, (_, i) => i);
  for (let i = 0; i < numUndefined; i++) {
    const idx = Math.floor(Math.random() * indices.length);
    const row = Math.floor(indices[idx] / 9);
    const col = indices[idx] % 9;
    grid[row][col] = undefined;
    indices.splice(idx, 1);
  }

  // Return the filled and partially empty grid
  return grid;
}
